def solve(path):
    """Simplify an absolute Unix path.
    Resolves ".", "..", removes redundant slashes, and removes trailing slash.
    The result always starts with '/' and root is returned as '/'.
    """
    parts = []
    for token in path.split('/'):
        if token == '' or token == '.':
